package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

type Node struct {
	char       byte
	index      int
	nextArray  [26]*Node
	hasCul     bool
	isSame     bool
	nextCount  int
	nextList   []*Node
	countArray []int64
}

func NewNode(char byte, index int, n int) *Node {
	return &Node{
		char:       char,
		index:      index,
		nextList:   make([]*Node, 0),
		countArray: make([]int64, n),
	}
}

func (node *Node) String() string {
	return string(node.char)
}

func (node *Node) addNext(index int, other *Node) {
	if node.nextArray[index] == nil {
		node.nextCount++
		node.nextArray[index] = other
		node.nextList = append(node.nextList, other)
	}
}

func find(node *Node) {
	if node.hasCul {
		return
	}

	node.countArray[0]++
	for _, next := range node.nextList {
		find(next)
		for i := 0; i < len(next.countArray); i++ {
			if next.countArray[i] > 0 {
				node.countArray[i+1] += next.countArray[i]
			}
		}
	}

	node.hasCul = true
}

type InputReader struct {
	scanner *bufio.Scanner
}

func NewInputReader(stream *os.File) *InputReader {
	scanner := bufio.NewScanner(stream)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)
	scanner.Split(bufio.ScanWords)
	return &InputReader{scanner: scanner}
}

func (r *InputReader) next() string {
	r.scanner.Scan()
	return r.scanner.Text()
}

func (r *InputReader) nextLong() int64 {
	v, _ := strconv.ParseInt(r.next(), 10, 64)
	return v
}

func (r *InputReader) nextInt() int {
	v, _ := strconv.Atoi(r.next())
	return v
}

func (r *InputReader) nextDouble() float64 {
	v, _ := strconv.ParseFloat(r.next(), 64)
	return v
}

func (r *InputReader) nextFloat() float64 {
	v, _ := strconv.ParseFloat(r.next(), 32)
	return v
}

func main() {
	inputReader := NewInputReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	n := inputReader.nextInt()
	k := inputReader.nextLong()
	str := inputReader.next()

	var letters [26]bool
	list := make([]*Node, 0, n)
	for i := 0; i < len(str); i++ {
		char := str[i]
		node := NewNode(char, i, n)
		if letters[char-'a'] {
			node.isSame = true
		} else {
			letters[char-'a'] = true
		}
		list = append(list, node)
	}
	for i := 0; i < len(list); i++ {
		ai := list[i]
		for j := i + 1; j < len(list); j++ {
			aj := list[j]
			ai.addNext(int(aj.char-'a'), aj)
		}
	}

	for _, node := range list {
		find(node)
	}

	totalCountArray := make([]int64, n)
	for i := 0; i < n; i++ {
		for _, node := range list {
			if !node.isSame {
				totalCountArray[i] += node.countArray[i]
			}
		}
	}

	var totalCost int64 = 0
	var selectCount int64 = 0
	for i := n - 1; i >= 0; i-- {
		if selectCount+totalCountArray[i] < k {
			totalCost += int64(n-1-i) * totalCountArray[i]
			selectCount += totalCountArray[i]
		} else {
			over := (selectCount + totalCountArray[i]) - k
			totalCost += int64(n-1-i) * (totalCountArray[i] - over)
			selectCount += totalCountArray[i] - over
			break
		}
	}

	if selectCount < k {
		if selectCount == k-1 {
			fmt.Fprintln(out, totalCost+int64(n))
		} else {
			fmt.Fprintln(out, -1)
		}
	} else {
		fmt.Fprintln(out, totalCost)
	}
}
